        <div className="flex items-center gap-3 border-t border-sidebar-border pt-4"><div className="grid h-8 w-8 place-items-center rounded-full bg-accent font-bold text-xs text-accent-foreground">AH</div><div className="min-w-0"><p className="truncate text-xs font-bold">Analyst workspace</p><p className="font-mono text-[10px] text-sidebar-foreground/45">local / demo</p></div><button onClick={() => window.alert('Workspace menu is available in the connected environment.')} className="ml-auto rounded-lg p-1 hover:bg-sidebar-accent" data-testid="button-workspace-menu"><MoreHorizontal size={16} className="text-sidebar-foreground/40" /></button></div>
