function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mb-2 font-mono text-[10px] font-medium uppercase tracking-[.2em] text-primary">{eyebrow}</p><h1 className="text-3xl font-extrabold tracking-[-.05em] text-foreground sm:text-[40px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>;
}

function LoadingBlock({ rows = 4 }: { rows?: number }) {
  return <div className="space-y-3" data-testid="status-loading">{Array.from({ length: rows }).map((_, i) => <div key={i} className="skeleton h-14 rounded-xl" />)}</div>;
}

function ErrorBlock({ onRetry }: { onRetry?: () => void }) {
  return <div className="rounded-2xl border border-accent/35 bg-accent/10 p-6 text-center" data-testid="status-error"><CircleHelp className="mx-auto mb-3 text-accent" size={25} /><p className="font-bold">We couldn't read this view</p><p className="mt-1 text-sm text-muted-foreground">The demo service may be waking up. Try once more.</p>{onRetry && <button onClick={onRetry} className="mt-4 inline-flex items-center gap-2 rounded-lg bg-foreground px-3 py-2 text-xs font-bold text-background hover:opacity-85" data-testid="button-retry"><RefreshCw size={14} /> Retry</button>}</div>;
}

function EmptyBlock({ label = 'Nothing here yet', action }: { label?: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card/50 px-6 py-12 text-center" data-testid="status-empty"><Layers3 className="mx-auto mb-3 text-muted-foreground/50" size={28} /><p className="font-bold">{label}</p>{action}</div>;
}

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'good' | 'warm' | 'neutral' | 'dark' }) {
  const styles = { good: 'bg-primary/10 text-primary border-primary/20', warm: 'bg-accent/12 text-accent border-accent/20', neutral: 'bg-muted text-muted-foreground border-border', dark: 'bg-foreground text-background border-foreground' };
  return <span className={`inline-flex items-center rounded-full border px-2 py-1 font-mono text-[10px] font-medium uppercase tracking-wider ${styles[tone]}`}>{children}</span>;
}

function StatCard({ label, value, sub, icon: Icon, tint = 'primary' }: { label: string; value: string; sub: string; icon: typeof Gauge; tint?: 'primary' | 'accent' }) {
  return <div className="group rounded-2xl border border-border bg-card p-5 shadow-[0_2px_0_hsl(var(--border))] transition-transform hover:-translate-y-0.5" data-testid={`card-stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="mb-7 flex items-start justify-between"><p className="font-mono text-[10px] uppercase tracking-[.15em] text-muted-foreground">{label}</p><span className={`rounded-lg p-2 ${tint === 'accent' ? 'bg-accent/15 text-accent' : 'bg-primary/12 text-primary'}`}><Icon size={16} /></span></div><p className="text-3xl font-extrabold tracking-[-.05em]">{value}</p><p className="mt-1 text-xs text-muted-foreground">{sub}</p></div>;
}

function DashboardPage() {
  const [, setLocation] = useLocation();
  const { data, isLoading, isError, refetch } = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  const createAnalysis = useCreateAnalysis();
  const [question, setQuestion] = useState('');
  const submit = () => { if (question.trim().length < 4) return; createAnalysis.mutate({ data: { question: question.trim() } }, { onSuccess: (result) => setLocation(`/analysis/${result.id}`) }); };
  const examples = ['Which regions show the strongest growth signal?', 'Find the biggest drivers behind churn last quarter', 'Compare quality across our connected sources'];
  return <div className="mx-auto max-w-[1420px] px-5 py-8 sm:px-8 lg:px-10">
    <div className="animate-rise relative overflow-hidden rounded-[26px] bg-foreground px-6 py-10 text-background sm:px-10 sm:py-12"><div className="paper-grid absolute inset-0 opacity-[.08]" /><div className="relative max-w-3xl"><div className="mb-5 flex items-center gap-2"><Sparkles size={16} className="text-accent" /><span className="font-mono text-[10px] uppercase tracking-[.2em] text-background/55">Plain English → transparent evidence</span></div><h1 className="max-w-2xl text-4xl font-extrabold leading-[1.02] tracking-[-.06em] sm:text-6xl">Ask a better question.<br /><span className="text-primary">See the proof.</span></h1><p className="mt-5 max-w-xl text-sm leading-6 text-background/62">InsightForge turns natural-language questions into auditable analysis plans, decision-ready charts, and evidence you can trace back to the record.</p><div className="mt-8 flex max-w-2xl items-center rounded-2xl border border-background/15 bg-background/10 p-2 backdrop-blur-sm focus-within:border-primary/70"><Search size={19} className="ml-3 shrink-0 text-background/45" /><input value={question} onChange={e => setQuestion(e.target.value)} onKeyDown={e => e.key === 'Enter' && submit()} placeholder="Ask your data anything…" className="min-w-0 flex-1 bg-transparent px-3 py-3 text-sm text-background outline-none placeholder:text-background/35" data-testid="input-dashboard-question" /><button onClick={submit} disabled={createAnalysis.isPending || question.trim().length < 4} className="inline-flex shrink-0 items-center gap-2 rounded-xl bg-primary px-4 py-3 text-xs font-bold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-40" data-testid="button-start-analysis">{createAnalysis.isPending ? <Loader2 className="animate-spin" size={15} /> : <ArrowRight size={15} />} Start analysis</button></div><div className="mt-4 flex flex-wrap gap-2">{examples.map((example, i) => <button key={example} onClick={() => setQuestion(example)} className="rounded-full border border-background/15 px-3 py-1.5 text-left text-[11px] text-background/55 hover:border-primary/60 hover:text-background" data-testid={`button-example-${i}`}>{example}</button>)}</div></div><div className="absolute -right-16 -top-20 hidden h-80 w-80 rounded-full border border-primary/20 lg:block"><div className="absolute inset-8 rounded-full border border-primary/20"><div className="absolute left-1/2 top-1/2 h-2 w-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-accent shadow-[0_0_0_9px_hsl(var(--accent)/.12)]" /></div></div></div>
    <section className="mt-8">{isLoading ? <LoadingBlock rows={1} /> : isError ? <ErrorBlock onRetry={() => refetch()} /> : <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Analyses completed" value={String(data?.stats.analysesCompleted ?? 0)} sub="Across this workspace" icon={BarChart3} /><StatCard label="Data sources" value={String(data?.stats.dataSources ?? 0)} sub="Connected and available" icon={Network} tint="accent" /><StatCard label="Records analyzed" value={(data?.stats.recordsAnalyzed ?? 0).toLocaleString()} sub="Evidence-backed rows" icon={Database} /><StatCard label="Average quality" value={`${data?.stats.averageQuality ?? 0}%`} sub="Across analyzed data" icon={ShieldCheck} tint="accent" /></div>}</section>
    {!isLoading && !isError && <div className="mt-10 grid gap-8 xl:grid-cols-[1.25fr_.75fr]"><section className="animate-rise delay-1"><div className="mb-4 flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">Recent work</p><h2 className="mt-1 text-xl font-extrabold tracking-[-.04em]">Analysis trail</h2></div><Link href="/history" className="inline-flex items-center gap-1 text-xs font-bold text-primary hover:gap-2" data-testid="link-view-history">View history <ArrowRight size={14} /></Link></div><div className="overflow-hidden rounded-2xl border border-border bg-card">{(data?.recentAnalyses?.length ?? 0) > 0 ? data?.recentAnalyses.map((analysis, i) => <Link href={`/analysis/${analysis.id}`} key={analysis.id} className="group flex items-center gap-4 border-b border-border px-5 py-4 last:border-0 hover:bg-muted/60" data-testid={`row-recent-analysis-${analysis.id}`}><span className="font-mono text-[11px] text-muted-foreground/55">0{i + 1}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{analysis.question}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{analysis.sources?.join(' · ')} <span className="mx-1 text-border">/</span>{analysis.records.toLocaleString()} records</p></div><Badge tone={analysis.quality >= 90 ? 'good' : 'warm'}>{analysis.quality}% quality</Badge><ArrowRight className="text-muted-foreground/40 transition-transform group-hover:translate-x-1" size={16} /></Link>) : <EmptyBlock label="Your first analysis is one question away." />}</div></section><section className="animate-rise delay-2"><div className="mb-4 flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Curated inputs</p><h2 className="mt-1 text-xl font-extrabold tracking-[-.04em]">Featured datasets</h2></div><Link href="/datasets" className="text-xs font-bold text-primary" data-testid="link-view-datasets">Browse all</Link></div><div className="space-y-3">{(data?.featuredDatasets?.length ?? 0) > 0 ? data?.featuredDatasets.slice(0, 3).map(dataset => <Link href={`/datasets?selected=${dataset.id}`} key={dataset.id} className="group block rounded-2xl border border-border bg-card p-4 hover:border-primary/50" data-testid={`card-featured-dataset-${dataset.id}`}><div className="flex items-center justify-between"><div className="flex items-center gap-3"><span className="rounded-lg bg-secondary p-2 text-primary"><Database size={16} /></span><div><p className="text-sm font-bold">{dataset.name}</p><p className="font-mono text-[10px] text-muted-foreground">{dataset.category} · {dataset.rows.toLocaleString()} rows</p></div></div><ChevronRight size={16} className="text-muted-foreground/40 transition-transform group-hover:translate-x-1" /></div><div className="mt-4 flex items-center justify-between"><span className="font-mono text-[10px] text-muted-foreground">{dataset.source}</span><Badge tone={dataset.synthetic ? 'warm' : 'good'}>{dataset.synthetic ? 'synthetic' : 'verified'} · {dataset.quality}%</Badge></div></Link>) : <EmptyBlock label="No featured datasets available." />}</div></section></div>}
  </div>;
}

function NewAnalysisPage() {
  const [, setLocation] = useLocation();
  const createAnalysis = useCreateAnalysis();
  const analyze = useAnalyzeQuery();
  const datasets = useGetDatasets();
  const [question, setQuestion] = useState('');
  const [datasetId, setDatasetId] = useState('');
  const [started, setStarted] = useState(false);
  const [createdId, setCreatedId] = useState<string | null>(null);
  const submit = () => { if (question.trim().length < 4) return; setStarted(true); createAnalysis.mutate({ data: { question: question.trim(), datasetId: datasetId || null } }, { onSuccess: (result) => { setCreatedId(result.id); analyze.mutate({ data: { question: question.trim(), datasetId: datasetId || null } }, { onSuccess: (analysis) => setLocation(`/analysis/${analysis.id || result.id}`), onError: () => setLocation(`/analysis/${result.id}`) }); } }); };
  const steps = ['Interpret the question', 'Select relevant evidence', 'Check data quality', 'Build decision-ready output'];
  return <div className="mx-auto max-w-[1120px] px-5 py-8 sm:px-8 lg:px-10"><PageHeading eyebrow="New analysis" title="Turn a question into proof." description="Start with what you need to know. InsightForge will make the reasoning visible before it makes the recommendation." action={<Badge tone="warm"><Zap size={11} className="mr-1" /> Demo mode</Badge>} /><div className="grid gap-8 lg:grid-cols-[1.15fr_.85fr]"><section className="rounded-2xl border border-border bg-card p-5 shadow-[0_2px_0_hsl(var(--border))] sm:p-7"><div className="mb-7 flex items-center justify-between"><div><h2 className="text-lg font-extrabold tracking-[-.04em]">Your analytical question</h2><p className="mt-1 text-xs text-muted-foreground">Be specific about the outcome you want to understand.</p></div><span className="font-mono text-[10px] text-muted-foreground">01 / 01</span></div><textarea value={question} onChange={e => setQuestion(e.target.value)} rows={5} placeholder="e.g. Which customer segments are most at risk of churn, and what signals explain the change?" className="w-full resize-none rounded-xl border border-input bg-background p-4 text-sm leading-6 outline-none ring-primary/20 placeholder:text-muted-foreground/60 focus:ring-4" data-testid="textarea-analysis-question" /><div className="mt-5"><label className="mb-2 block font-mono text-[10px] uppercase tracking-[.15em] text-muted-foreground">Scope to a dataset <span className="normal-case tracking-normal">(optional)</span></label><select value={datasetId} onChange={e => setDatasetId(e.target.value)} className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-4 focus:ring-primary/15" data-testid="select-analysis-dataset"><option value="">Let InsightForge choose the best evidence</option>{datasets.data?.map(dataset => <option key={dataset.id} value={dataset.id}>{dataset.name}{dataset.synthetic ? ' · synthetic' : ''}</option>)}</select></div><button onClick={submit} disabled={started || question.trim().length < 4} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 text-sm font-bold text-primary-foreground hover:-translate-y-0.5 hover:shadow-[0_4px_0_hsl(var(--accent))] disabled:cursor-not-allowed disabled:opacity-40" data-testid="button-run-new-analysis">{started ? <><Loader2 className="animate-spin" size={17} /> {analyze.isPending ? 'Running analysis…' : 'Preparing evidence…'}</> : <><Play size={17} /> Build transparent analysis</>}</button>{(createAnalysis.isError || analyze.isError) && <p className="mt-3 text-center text-xs text-destructive">We couldn't run that question. Try a more specific prompt.</p>}</section><section className="relative rounded-2xl border border-border bg-foreground p-6 text-background sm:p-7"><div className="absolute right-6 top-6 rounded-full border border-background/15 px-2 py-1 font-mono text-[9px] uppercase tracking-wider text-background/45">live trace</div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">Execution timeline</p><h2 className="mt-2 text-xl font-extrabold tracking-[-.04em]">A visible chain of thought.</h2><p className="mt-2 text-xs leading-5 text-background/55">No black-box answer. Every result carries its route to the underlying data.</p><div className="mt-10 space-y-0">{steps.map((step, i) => <div key={step} className="relative flex gap-4 pb-7 last:pb-0"><div className={`relative z-10 grid h-7 w-7 shrink-0 place-items-center rounded-full border ${started && i === 0 ? 'border-primary bg-primary text-primary-foreground' : started && i < 2 ? 'border-primary/60 text-primary' : 'border-background/20 text-background/35'}`}>{started && i === 0 ? <Loader2 size={13} className="animate-spin" /> : started && i < 2 ? <Check size={13} /> : <span className="font-mono text-[10px]">{i + 1}</span>}</div>{i < steps.length - 1 && <span className="absolute left-[13px] top-7 h-full w-px bg-background/15" />}<div><p className={`text-xs font-bold ${started && i < 2 ? 'text-primary' : 'text-background/75'}`}>{step}</p><p className="mt-1 text-[11px] leading-5 text-background/45">{i === 0 ? 'Translate intent into a measurable plan' : i === 1 ? 'Trace relevant fields and records' : i === 2 ? 'Surface gaps, outliers, and confidence' : 'Return the answer with evidence attached'}</p></div></div>)}</div>{createdId && <p className="mt-8 border-t border-background/15 pt-4 font-mono text-[10px] text-background/45">trace id <span className="text-primary">{createdId}</span></p>}</section></div></div>;
}

function TinyChart({ chart, compact = false }: { chart: any; compact?: boolean }) {
  const values = (chart?.data ?? []).map((row: any) => Number(row[chart.yKey]) || Number(Object.values(row)[1]) || 0);
  const max = Math.max(...values, 1);
  const points = values.map((v: number, i: number) => `${(i / Math.max(values.length - 1, 1)) * 100},${94 - (v / max) * 74}`).join(' ');
  return <div className={`relative ${compact ? 'h-24' : 'h-48'}`}><svg className="h-full w-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M 0 94 L 100 94" stroke="hsl(var(--border))" strokeWidth=".6" vectorEffect="non-scaling-stroke" /><polyline points={points} fill="none" stroke="hsl(var(--primary))" strokeWidth="2.4" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" />{values.map((v: number, i: number) => <circle key={i} cx={(i / Math.max(values.length - 1, 1)) * 100} cy={94 - (v / max) * 74} r="2.2" fill="hsl(var(--card))" stroke="hsl(var(--accent))" strokeWidth="1.5" vectorEffect="non-scaling-stroke" />)}</svg><div className="absolute inset-x-0 bottom-0 flex justify-between font-mono text-[9px] text-muted-foreground">{(chart?.data ?? []).slice(0, 5).map((row: any, i: number) => <span key={i}>{String(row[chart.xKey] ?? Object.values(row)[0]).slice(0, 10)}</span>)}</div></div>;
}

function QualityPanel({ quality }: { quality: any }) {
  const score = quality ? Math.max(0, Math.round(100 - ((quality.missing + quality.duplicates + quality.invalid) / Math.max(quality.rows, 1)) * 100)) : 0;
  return <section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.17em] text-primary">Data quality</p><h2 className="mt-1 text-lg font-extrabold tracking-[-.03em]">Know what to trust.</h2></div><div className="text-right"><p className="text-3xl font-extrabold tracking-[-.06em] text-primary">{score}%</p><p className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">quality score</p></div></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${score}%` }} /></div><p className="mt-4 text-xs leading-5 text-muted-foreground">{quality?.explanation}</p><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{[['Rows', quality?.rows], ['Missing', quality?.missing], ['Duplicates', quality?.duplicates], ['Outliers', quality?.outliers]].map(([label, value]) => <div key={label as string} className="rounded-xl bg-muted/70 p-3"><p className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-1 text-sm font-bold">{Number(value ?? 0).toLocaleString()}</p></div>)}</div></section>;
}

function AnalysisResultsPage() {
  const { id = '' } = useParams<{ id: string }>();
  const { data, isLoading, isError, refetch } = useGetAnalysis(id, { query: { queryKey: getGetAnalysisQueryKey(id) } });
  const followUp = useAskAnalysisFollowUp();
  const simulation = useRunSimulation();
  const [followQuestion, setFollowQuestion] = useState('');
  const [answer, setAnswer] = useState<any>(null);
  const [sim, setSim] = useState<any>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'evidence'>('overview');
  if (isLoading) return <div className="mx-auto max-w-[1200px] px-5 py-10 sm:px-8"><LoadingBlock rows={5} /></div>;
  if (isError || !data) return <div className="mx-auto max-w-[900px] px-5 py-16 sm:px-8"><ErrorBlock onRetry={() => refetch()} /></div>;
  const runFollowUp = () => { if (followQuestion.trim().length < 2) return; followUp.mutate({ id, data: { question: followQuestion } }, { onSuccess: result => { setAnswer(result); setFollowQuestion(''); } }); };
  const runSim = () => simulation.mutate({ data: { baseline: data.whatIf.current, changePercent: 10, label: data.whatIf.label } }, { onSuccess: result => setSim(result) });
  return <div className="mx-auto max-w-[1280px] px-5 py-8 sm:px-8 lg:px-10"><div className="mb-7 flex flex-wrap items-start justify-between gap-4"><div><Link href="/history" className="mb-4 inline-flex items-center gap-1 text-xs font-bold text-muted-foreground hover:text-primary" data-testid="link-back-history"><ChevronLeft size={14} /> Analysis history</Link><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">Analysis / {id}</p><h1 className="mt-2 max-w-4xl text-2xl font-extrabold leading-tight tracking-[-.05em] sm:text-4xl">{data.question}</h1><div className="mt-3 flex flex-wrap gap-2"><Badge tone="good"><Check size={11} className="mr-1" /> {data.status}</Badge><Badge tone="neutral">{data.records.toLocaleString()} records</Badge>{data.sources?.map(source => <Badge key={source}>{source}</Badge>)}</div></div><div className="flex items-center gap-2"><Link href="/reports" className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-3 py-2 text-xs font-bold hover:border-primary" data-testid="link-generate-report"><FileBarChart size={15} /> Generate report</Link></div></div><div className="mb-6 flex gap-1 border-b border-border"><button onClick={() => setActiveTab('overview')} className={`border-b-2 px-4 py-3 text-xs font-bold ${activeTab === 'overview' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`} data-testid="tab-analysis-overview">Overview</button><button onClick={() => setActiveTab('evidence')} className={`border-b-2 px-4 py-3 text-xs font-bold ${activeTab === 'evidence' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`} data-testid="tab-analysis-evidence">Evidence ledger ({data.evidence?.length ?? 0})</button></div>{activeTab === 'overview' ? <div className="grid gap-6 lg:grid-cols-[1.35fr_.65fr]"><div className="space-y-6"><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.17em] text-primary">Executive readout</p><h2 className="mt-1 text-lg font-extrabold tracking-[-.03em]">What the data says</h2></div><Badge tone="good"><ShieldCheck size={11} className="mr-1" /> traceable</Badge></div><div className="mt-5 grid gap-3">{data.insights?.map((insight: any, i: number) => <div key={insight.id} className="group rounded-xl border border-border bg-background p-4 transition-colors hover:border-primary/50" data-testid={`card-insight-${insight.id}`}><div className="flex gap-4"><span className="font-mono text-sm font-bold text-accent">0{i + 1}</span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><h3 className="text-sm font-extrabold">{insight.title}</h3><span className="font-mono text-[10px] text-primary">{insight.confidence}% confidence</span></div><p className="mt-2 text-xs leading-5 text-muted-foreground">{insight.explanation}</p><div className="mt-3 flex flex-wrap items-center gap-2"><Badge tone="dark">{insight.metric}</Badge><span className="text-[11px] text-muted-foreground">{insight.comparison}</span><span className="ml-auto inline-flex items-center gap-1 font-mono text-[10px] text-primary"><BookOpen size={11} /> {insight.evidenceId}</span></div></div></div></div>)}</div></section><section className="grid gap-6 md:grid-cols-2">{data.charts?.map((chart: any) => <div key={chart.id} className="rounded-2xl border border-border bg-card p-5"><div className="mb-5 flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.17em] text-muted-foreground">{chart.type} view</p><h3 className="mt-1 text-sm font-extrabold">{chart.title}</h3></div><LineChart size={16} className="text-primary" /></div><TinyChart chart={chart} /><p className="mt-4 text-[11px] leading-5 text-muted-foreground">{chart.note}</p></div>)}</section><QualityPanel quality={data.qualityDetails} /></div><aside className="space-y-6"><section className="rounded-2xl border border-border bg-foreground p-5 text-background sm:p-6"><p className="font-mono text-[10px] uppercase tracking-[.17em] text-primary">Transparent plan</p><h2 className="mt-1 text-lg font-extrabold tracking-[-.03em]">How we got there</h2><p className="mt-4 text-xs leading-5 text-background/55">{data.plan?.goal}</p><div className="mt-5 space-y-3">{data.steps?.map((step: any) => <div key={step.id} className="flex gap-3"><span className={`mt-0.5 grid h-5 w-5 shrink-0 place-items-center rounded-full ${step.status === 'complete' ? 'bg-primary text-primary-foreground' : 'border border-background/25 text-background/50'}`}>{step.status === 'complete' ? <Check size={11} /> : <span className="font-mono text-[9px]">·</span>}</span><div><p className="text-xs font-bold">{step.label}</p><p className="mt-1 text-[10px] leading-4 text-background/45">{step.detail}</p></div></div>)}</div><div className="mt-6 border-t border-background/15 pt-5"><p className="font-mono text-[9px] uppercase tracking-wider text-background/40">Operations</p><p className="mt-2 text-[11px] leading-5 text-background/65">{data.plan?.operations?.join(' · ')}</p></div></section><section className="rounded-2xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.17em] text-accent">What-if lens</p><h2 className="mt-1 text-lg font-extrabold tracking-[-.03em]">{data.whatIf.label}</h2></div><Zap size={18} className="text-accent" /></div><div className="mt-5 flex items-end justify-between"><div><p className="font-mono text-[9px] uppercase text-muted-foreground">Current</p><p className="text-2xl font-extrabold">{data.whatIf.current.toLocaleString()}</p></div><ArrowRight className="mb-2 text-muted-foreground" size={18} /><div className="text-right"><p className="font-mono text-[9px] uppercase text-muted-foreground">+10% scenario</p><p className="text-2xl font-extrabold text-primary">{(sim?.simulated ?? data.whatIf.simulated).toLocaleString()}</p></div></div><button onClick={runSim} disabled={simulation.isPending} className="mt-5 flex w-full items-center justify-center gap-2 rounded-lg border border-primary/30 bg-primary/8 px-3 py-2.5 text-xs font-bold text-primary hover:bg-primary/15" data-testid="button-run-simulation">{simulation.isPending ? <Loader2 size={14} className="animate-spin" /> : <Play size={14} />} Run deterministic simulation</button>{sim && <p className="mt-3 text-center font-mono text-[10px] text-primary">{sim.percent}% projected change · {sim.difference > 0 ? '+' : ''}{sim.difference.toLocaleString()} difference</p>}</section></aside></div> : <section className="space-y-4">{data.evidence?.map((item: any) => <div key={item.id} className="rounded-2xl border border-border bg-card p-5 sm:p-6" data-testid={`card-evidence-${item.id}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><Badge tone="dark">{item.id}</Badge><span className="font-mono text-[10px] text-muted-foreground">{item.timestamp}</span></div><h2 className="mt-3 text-base font-extrabold">{item.insight}</h2></div><Badge tone="good"><Database size={11} className="mr-1" /> {item.records.toLocaleString()} records</Badge></div><div className="mt-5 grid gap-4 border-t border-border pt-4 sm:grid-cols-3"><div><p className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Dataset</p><p className="mt-1 text-xs font-bold">{item.dataset}</p></div><div><p className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Calculation</p><p className="mt-1 text-xs font-bold">{item.calculation}</p></div><div><p className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Fields</p><p className="mt-1 text-xs font-bold">{item.fields?.join(' · ')}</p></div></div><p className="mt-4 rounded-lg bg-muted p-3 font-mono text-[11px] leading-5 text-muted-foreground">source: {item.source}</p></div>)}</section>}<section className="mt-6 rounded-2xl border border-primary/25 bg-primary/7 p-5 sm:p-6"><div className="flex items-start gap-3"><div className="rounded-lg bg-primary p-2 text-primary-foreground"><Sparkles size={16} /></div><div className="flex-1"><p className="font-mono text-[10px] uppercase tracking-[.17em] text-primary">Ask a follow-up</p><h2 className="mt-1 text-base font-extrabold">Keep the evidence in context.</h2><div className="mt-4 flex items-center rounded-xl border border-primary/20 bg-card p-1.5"><input value={followQuestion} onChange={e => setFollowQuestion(e.target.value)} onKeyDown={e => e.key === 'Enter' && runFollowUp()} placeholder="What else should I investigate?" className="min-w-0 flex-1 bg-transparent px-3 py-2 text-xs outline-none placeholder:text-muted-foreground/60" data-testid="input-follow-up" /><button onClick={runFollowUp} disabled={followUp.isPending || followQuestion.trim().length < 2} className="rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground disabled:opacity-40" data-testid="button-submit-follow-up">{followUp.isPending ? <Loader2 size={14} className="animate-spin" /> : <ArrowRight size={14} />}</button></div>{answer && <div className="mt-4 rounded-xl border border-border bg-card p-4"><p className="text-sm font-bold">{answer.answer}</p><p className="mt-2 text-xs leading-5 text-muted-foreground">{answer.context}</p></div>}</div></div></section></div>;
}

function HistoryPage() {
  const { data, isLoading, isError, refetch } = useGetAnalyses({ query: { queryKey: getGetAnalysesQueryKey() } });
  const remove = useDeleteAnalysis();
  const [search, setSearch] = useState('');
  const filtered = useMemo(() => data?.filter(item => item.question.toLowerCase().includes(search.toLowerCase()) || item.sources?.some(s => s.toLowerCase().includes(search.toLowerCase()))) ?? [], [data, search]);
  return <div className="mx-auto max-w-[1200px] px-5 py-8 sm:px-8 lg:px-10"><PageHeading eyebrow="Analysis history" title="A record of every answer." description="Search, revisit, and remove analysis runs from this workspace." action={<Link href="/analysis/new" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground hover:-translate-y-0.5" data-testid="link-new-analysis"><Plus size={15} /> New analysis</Link>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search questions or sources…" className="w-full rounded-xl border border-input bg-card py-3 pl-10 pr-4 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="input-search-history" /></div><button onClick={() => window.alert('Advanced filters are not needed in deterministic demo mode.')} className="inline-flex items-center justify-center gap-2 rounded-xl border border-border bg-card px-4 py-3 text-xs font-bold hover:bg-muted" data-testid="button-filter-history"><Filter size={15} /> Filters</button></div>{isLoading ? <LoadingBlock rows={5} /> : isError ? <ErrorBlock onRetry={() => refetch()} /> : filtered.length === 0 ? <EmptyBlock label={search ? 'No analyses match that search.' : 'No analyses yet.'} action={!search ? <Link href="/analysis/new" className="mt-4 inline-flex rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground" data-testid="link-empty-new-analysis">Ask your first question</Link> : undefined} /> : <div className="overflow-hidden rounded-2xl border border-border bg-card">{filtered.map((item, i) => <div key={item.id} className="group flex flex-col gap-4 border-b border-border p-5 last:border-0 sm:flex-row sm:items-center" data-testid={`row-analysis-${item.id}`}><span className="hidden w-7 font-mono text-[11px] text-muted-foreground/50 sm:block">{String(i + 1).padStart(2, '0')}</span><Link href={`/analysis/${item.id}`} className="min-w-0 flex-1"><p className="text-sm font-bold group-hover:text-primary">{item.question}</p><div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 font-mono text-[10px] text-muted-foreground"><span>{new Date(item.createdAt).toLocaleDateString()}</span><span>{item.records.toLocaleString()} records</span><span>{item.sources?.join(' · ')}</span></div></Link><div className="flex items-center gap-3"><Badge tone={item.quality >= 90 ? 'good' : 'warm'}>{item.quality}% quality</Badge><Badge>{item.status}</Badge><button onClick={() => { if (window.confirm('Delete this analysis?')) remove.mutate({ id: item.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetAnalysesQueryKey() }) }); }} className="rounded-lg p-2 text-muted-foreground/50 hover:bg-accent/10 hover:text-accent" data-testid={`button-delete-analysis-${item.id}`}><Trash2 size={15} /></button></div></div>)}</div>}</div>;
}

function DatasetsPage() {
  const client = useQueryClient();
  const { data, isLoading, isError, refetch } = useGetDatasets({ query: { queryKey: getGetDatasetsQueryKey() } });
  const create = useCreateDataset();
  const remove = useDeleteDataset();
  const [selected, setSelected] = useState<string | null>(null);
  const detail = useGetDataset(selected ?? '', { query: { enabled: !!selected, queryKey: getGetDatasetQueryKey(selected ?? '') } });
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: '', source: 'Uploaded CSV', category: 'Custom', rows: '1200', columns: '14', quality: '94' });
  const submit = () => create.mutate({ data: { ...form, rows: Number(form.rows), columns: Number(form.columns), quality: Number(form.quality) } }, { onSuccess: () => { setShowForm(false); setForm({ ...form, name: '' }); client.invalidateQueries({ queryKey: getGetDatasetsQueryKey() }); } });
  return <div className="mx-auto max-w-[1250px] px-5 py-8 sm:px-8 lg:px-10"><PageHeading eyebrow="Data library" title="Datasets with provenance." description="Inspect the inputs behind every analysis. Synthetic data is always labeled." action={<button onClick={() => setShowForm(v => !v)} className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground hover:-translate-y-0.5" data-testid="button-add-dataset"><Plus size={15} /> Register dataset</button>} />{showForm && <div className="mb-6 rounded-2xl border border-primary/30 bg-primary/5 p-5"><div className="mb-4 flex items-center justify-between"><h2 className="font-extrabold">Register a dataset</h2><button onClick={() => setShowForm(false)} data-testid="button-close-dataset-form"><X size={17} /></button></div><div className="grid gap-3 sm:grid-cols-3"><input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Dataset name" className="rounded-lg border border-input bg-card px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary/20 sm:col-span-2" data-testid="input-dataset-name" /><input value={form.category} onChange={e => setForm({ ...form, category: e.target.value })} placeholder="Category" className="rounded-lg border border-input bg-card px-3 py-2.5 text-sm outline-none" data-testid="input-dataset-category" /></div><div className="mt-4 flex flex-wrap gap-3"><button onClick={submit} disabled={!form.name.trim() || create.isPending} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground disabled:opacity-40" data-testid="button-submit-dataset">{create.isPending ? <Loader2 className="animate-spin" size={14} /> : <Upload size={14} />} Register synthetic dataset</button><p className="self-center font-mono text-[10px] text-muted-foreground">Demo records are deterministic.</p></div></div>}{isLoading ? <LoadingBlock rows={5} /> : isError ? <ErrorBlock onRetry={() => refetch()} /> : <div className="overflow-x-auto rounded-2xl border border-border bg-card"><table className="w-full min-w-[760px] text-left"><thead className="bg-muted/70 font-mono text-[10px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-4">Dataset</th><th className="px-5 py-4">Source</th><th className="px-5 py-4">Shape</th><th className="px-5 py-4">Quality</th><th className="px-5 py-4">Updated</th><th className="px-5 py-4" /></tr></thead><tbody>{data?.map(dataset => <tr key={dataset.id} className="group border-t border-border hover:bg-muted/40" data-testid={`row-dataset-${dataset.id}`}><td className="px-5 py-4"><button onClick={() => setSelected(dataset.id)} className="text-left" data-testid={`button-preview-dataset-${dataset.id}`}><p className="text-sm font-bold group-hover:text-primary">{dataset.name}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{dataset.category} · {dataset.synthetic ? 'synthetic demo' : 'connected'}</p></button></td><td className="px-5 py-4 text-xs text-muted-foreground">{dataset.source}</td><td className="px-5 py-4 font-mono text-xs">{dataset.rows.toLocaleString()} × {dataset.columns}</td><td className="px-5 py-4"><Badge tone={dataset.quality >= 90 ? 'good' : 'warm'}>{dataset.quality}%</Badge></td><td className="px-5 py-4 font-mono text-[10px] text-muted-foreground">{dataset.updated}</td><td className="px-5 py-4 text-right"><button onClick={() => { if (window.confirm(`Delete ${dataset.name}?`)) remove.mutate({ id: dataset.id }, { onSuccess: () => client.invalidateQueries({ queryKey: getGetDatasetsQueryKey() }) }); }} className="rounded-lg p-2 text-muted-foreground/50 hover:bg-accent/10 hover:text-accent" data-testid={`button-delete-dataset-${dataset.id}`}><Trash2 size={15} /></button></td></tr>)}</tbody></table></div>}{selected && <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/25 p-4 backdrop-blur-sm sm:items-center" onClick={() => setSelected(null)}><div className="max-h-[85vh] w-full max-w-3xl overflow-auto rounded-2xl border border-border bg-card p-5 shadow-2xl sm:p-7" onClick={e => e.stopPropagation()} data-testid="panel-dataset-preview"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.17em] text-primary">Dataset preview</p><h2 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">{detail.data?.name ?? 'Loading preview…'}</h2></div><button onClick={() => setSelected(null)} className="rounded-lg p-2 hover:bg-muted" data-testid="button-close-dataset-preview"><X size={18} /></button></div>{detail.isLoading ? <div className="mt-6"><LoadingBlock rows={4} /></div> : detail.data && <><div className="mt-5 flex flex-wrap gap-2"><Badge tone="warm">{detail.data.synthetic ? 'synthetic demo data' : detail.data.source}</Badge><Badge>{detail.data.rows.toLocaleString()} rows</Badge><Badge>{detail.data.fields.length} fields</Badge></div><div className="mt-6 overflow-x-auto rounded-xl border border-border"><table className="w-full min-w-[500px] text-left text-xs"><thead className="bg-muted font-mono text-[9px] uppercase text-muted-foreground"><tr>{detail.data.fields.map(field => <th key={field} className="px-3 py-3">{field}</th>)}</tr></thead><tbody>{detail.data.preview.slice(0, 7).map((row: any, i: number) => <tr key={i} className="border-t border-border">{detail.data?.fields.map(field => <td key={field} className="px-3 py-3 font-mono text-[10px]">{String(row[field] ?? '—')}</td>)}</tr>)}</tbody></table></div></>}</div></div>}</div>;
}

function SourcesPage() {
  const { data, isLoading, isError, refetch } = useGetDataSources();
  return <div className="mx-auto max-w-[1180px] px-5 py-8 sm:px-8 lg:px-10"><PageHeading eyebrow="Data sources" title="Know what is connected." description="A transparent inventory of the sources available to your analytical workspace." action={<Badge tone="good"><span className="mr-1 h-1.5 w-1.5 rounded-full bg-primary" /> demo environment</Badge>} />{isLoading ? <LoadingBlock rows={4} /> : isError ? <ErrorBlock onRetry={() => refetch()} /> : <div className="grid gap-4 md:grid-cols-2">{data?.map(source => <article key={source.id} className="group rounded-2xl border border-border bg-card p-5 transition-transform hover:-translate-y-0.5 hover:border-primary/50" data-testid={`card-source-${source.id}`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><span className="rounded-xl bg-secondary p-3 text-primary"><Database size={20} /></span><div><h2 className="text-sm font-extrabold">{source.name}</h2><p className="mt-1 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{source.type}</p></div></div><Badge tone={source.status === 'active' ? 'good' : 'warm'}>{source.status}</Badge></div><p className="mt-5 text-xs leading-5 text-muted-foreground">{source.description}</p><div className="mt-5 grid grid-cols-3 gap-3 border-t border-border pt-4"><div><p className="font-mono text-[9px] uppercase text-muted-foreground">Records</p><p className="mt-1 text-sm font-bold">{source.records.toLocaleString()}</p></div><div><p className="font-mono text-[9px] uppercase text-muted-foreground">Quality</p><p className="mt-1 text-sm font-bold text-primary">{source.quality}%</p></div><div><p className="font-mono text-[9px] uppercase text-muted-foreground">Updated</p><p className="mt-1 text-xs font-bold">{source.updated}</p></div></div></article>)}</div>}</div>;
}

function ReportsPage() {
  const analyses = useGetAnalyses();
  const create = useCreateReport();
  const [format, setFormat] = useState<'json' | 'csv' | 'print'>('json');
  const [reports, setReports] = useState<any[]>([]);
  const generate = () => { const first = analyses.data?.[0]; if (!first) return; create.mutate({ data: { analysisId: first.id, format } }, { onSuccess: report => setReports(current => [report, ...current]) }); };
  return <div className="mx-auto max-w-[1100px] px-5 py-8 sm:px-8 lg:px-10"><PageHeading eyebrow="Reports" title="Package the evidence." description="Generate a portable record of your analysis for review, sharing, or a judging panel." /><div className="grid gap-6 lg:grid-cols-[.82fr_1.18fr]"><section className="rounded-2xl border border-border bg-foreground p-6 text-background"><FileBarChart className="mb-6 text-primary" size={28} /><h2 className="text-2xl font-extrabold tracking-[-.05em]">Generate a report</h2><p className="mt-2 text-xs leading-5 text-background/55">Select an output format. Reports include the question, method, findings, quality notes, and evidence ledger.</p><label className="mt-7 block font-mono text-[10px] uppercase tracking-wider text-background/45">Format</label><div className="mt-2 grid grid-cols-3 gap-2">{(['json', 'csv', 'print'] as const).map(item => <button key={item} onClick={() => setFormat(item)} className={`rounded-lg border p-3 text-left font-mono text-[10px] uppercase tracking-wider ${format === item ? 'border-primary bg-primary/15 text-primary' : 'border-background/15 text-background/55 hover:border-background/35'}`} data-testid={`button-format-${item}`}>{item}<span className="mt-1 block text-[9px] normal-case tracking-normal opacity-60">{item === 'json' ? 'structured' : item === 'csv' ? 'spreadsheet' : 'print-ready'}</span></button>)}</div><button onClick={generate} disabled={create.isPending || !analyses.data?.length} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-xs font-bold text-primary-foreground disabled:opacity-40" data-testid="button-generate-report">{create.isPending ? <Loader2 size={15} className="animate-spin" /> : <Download size={15} />} Generate from latest analysis</button>{!analyses.data?.length && <p className="mt-3 text-center text-[11px] text-background/45">Complete an analysis before generating a report.</p>}</section><section><div className="mb-4 flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">Export history</p><h2 className="mt-1 text-xl font-extrabold tracking-[-.04em]">Generated reports</h2></div><Badge>{reports.length} this session</Badge></div>{reports.length === 0 ? <EmptyBlock label="Reports generated this session will appear here." /> : <div className="space-y-3">{reports.map(report => <div key={report.id} className="flex items-center gap-4 rounded-2xl border border-border bg-card p-4" data-testid={`row-report-${report.id}`}><span className="rounded-lg bg-primary/10 p-2 text-primary"><FileBarChart size={17} /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{report.title}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{report.format} · {new Date(report.generatedAt).toLocaleString()}</p></div><Badge tone="good">ready</Badge></div>)}</div>}</section></div></div>;
}

function Router() {
  return <RoutedErrorBoundary><Shell><Switch><Route path="/" component={DashboardPage} /><Route path="/analysis/new" component={NewAnalysisPage} /><Route path="/analysis/:id" component={AnalysisResultsPage} /><Route path="/history" component={HistoryPage} /><Route path="/datasets" component={DatasetsPage} /><Route path="/sources" component={SourcesPage} /><Route path="/reports" component={ReportsPage} /><Route component={NotFound} /></Switch></Shell></RoutedErrorBoundary>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;